//! Definitions of the Abstract Syntax Tree (AST).
//! This is the part of declarations.

use super::expressions::*;
use super::statements::*;
use super::symbols::*;

#[derive(Debug)]
pub enum FuncDef {
    Default(BType, IDENT, Vec<FuncFParam>, Block),
}

#[derive(Debug)]
pub enum FuncFParam {
    Default(BType, IDENT, Option<Vec<Exp>>),
}

#[derive(Debug)]
pub enum Block {
    Default(Vec<BlockItem>), // May have 0 or more items.
}

#[derive(Debug)]
pub enum BlockItem {
    Decl(Decl),
    Stmt(Stmt),
}

#[derive(Debug)]
pub enum InitVal {
    Exp(Exp),
    Aggregate(Vec<Box<InitVal>>),
}

#[derive(Debug)]
pub enum Decl {
    ConstDecl(ConstDecl),
    VarDecl(VarDecl),
}

#[derive(Debug)]
pub enum ConstDecl {
    Default(BType, Vec<ConstDef>),
}

#[derive(Debug)]
pub enum ConstDef {
    Default(IDENT, Vec<Exp>, InitVal),
}

#[derive(Debug)]
pub enum VarDecl {
    Default(BType, Vec<VarDef>),
}

#[derive(Debug)]
pub enum VarDef {
    Default(IDENT, Vec<Exp>, Option<InitVal>),
}

//! Definitions of the Abstract Syntax Tree (AST).
//! This is the part of expressions.

use super::symbols::*;

#[derive(Debug)]
pub enum Exp {
    LOrExp(LOrExp),
}

#[derive(Debug)]
pub enum LOrExp {
    LAndExp(LAndExp),
    BinaryLOrExp(Box<LOrExp>, LAndExp),
}

#[derive(Debug)]
pub enum LAndExp {
    EqExp(EqExp),
    BinaryLAndExp(Box<LAndExp>, EqExp),
}

#[derive(Debug)]
pub enum EqExp {
    RelExp(RelExp),
    BinaryEqExp(Box<EqExp>, RelExp),
    BinaryUneqExp(Box<EqExp>, RelExp),
}

#[derive(Debug)]
pub enum RelExp {
    AddExp(AddExp),
    BinaryLtExp(Box<RelExp>, AddExp),
    BinaryGtExp(Box<RelExp>, AddExp),
    BinaryLeExp(Box<RelExp>, AddExp),
    BinaryGeExp(Box<RelExp>, AddExp),
}

#[derive(Debug)]
pub enum AddExp {
    MulExp(MulExp),
    BinaryAddExp(Box<AddExp>, MulExp),
    BinarySubExp(Box<AddExp>, MulExp),
}

#[derive(Debug)]
pub enum MulExp {
    UnaryExp(UnaryExp),
    BinaryMulExp(Box<MulExp>, UnaryExp),
    BinaryDivExp(Box<MulExp>, UnaryExp),
    BinaryModExp(Box<MulExp>, UnaryExp),
}

#[derive(Debug)]
pub enum UnaryExp {
    PrimaryExp(PrimaryExp),
    PlusUnaryExp(Box<UnaryExp>),
    MinusUnaryExp(Box<UnaryExp>),
    NotUnaryExp(Box<UnaryExp>),
    FuncCall(IDENT, Vec<Exp>),
}

#[derive(Debug)]
pub enum PrimaryExp {
    BracedExp(Box<Exp>),
    LVal(LVal),
    Number(Number),
}

#[derive(Debug)]
pub enum LVal {
    Default(IDENT, Vec<Exp>),
}

#[derive(Debug)]
pub enum Number {
    INTCONST(i32),
}

//! Definitions of the Abstract Syntax Tree (AST).
//! This is the part of statements.

use super::declarations::*;
use super::expressions::*;

#[derive(Debug)]
pub enum Stmt {
    UnmatchedStmt(UnmatchedStmt),
    MatchedStmt(MatchedStmt),
}

#[derive(Debug)]
pub struct UnmatchedStmt {
    pub default: BasicStmt,
}

#[derive(Debug)]
pub struct MatchedStmt {
    pub default: BasicStmt,
}

#[derive(Debug)]
pub enum BasicStmt {
    AssignStmt(LVal, Exp),
    Exp(Option<Exp>),
    Block(Block),
    IfStmt(Exp, Box<BasicStmt>, Box<Option<BasicStmt>>),
    WhileStmt(Exp, Box<BasicStmt>),
    BreakStmt,
    ContinueStmt,
    ReturnStmt(Option<Exp>),
}

