    let mut dfg = DataFlowGraph::new();
    let params = params_ty
      .iter()
      .enumerate()
      .map(|(i, ty)| dfg.new_value_data(FuncArgRef::new_data(i, ty.clone())))
      .collect();
    Self {
      ty: Type::get_function(params_ty, ret_ty),
